def humanize(integer: int) -> str:
    """Create a human-compatible ID from and integer"""
    if integer is None:
        return None
    b32 = b32encode(int_to_bytes(integer))
    return b32.decode("ascii").replace("O", "8").replace("I", "9").rstrip("=")

